import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        skipinitialspace=True,
        strict=False,
    )

    parsed_rows = []
    for row in reader:
        cleaned = [cell.strip() for cell in row]
        if any(cleaned):
            parsed_rows.append(cleaned)

    if not parsed_rows:
        return {"columns": [], "rows": []}

    header_index = None
    for index, row in enumerate(parsed_rows):
        first = row[0].lstrip("\ufeff").strip()
        if first.startswith("#") and len(row) > 1:
            header_index = index
            break

    if header_index is None:
        header_index = 0
        columns = parsed_rows[header_index][:]
    else:
        columns = parsed_rows[header_index][:]
        columns[0] = columns[0].lstrip("\ufeff").strip()[1:].strip()

    data_rows = []
    for row in parsed_rows[header_index + 1:]:
        if row[0].lstrip().startswith("#"):
            continue
        data_rows.append(row)

    width = max([len(columns)] + [len(row) for row in data_rows])
    columns.extend([""] * (width - len(columns)))
    normalized_rows = [
        row + [""] * (width - len(row))
        for row in data_rows
    ]

    return {"columns": columns, "rows": normalized_rows}
